{
  "name": "@humaiz/opencode-cmdsync",
  "version": "0.1.0",
  "description": "OpenCode provider plugin that exposes the current Command Code GOAT model catalog.",
  "type": "module",
  "publishConfig": {
    "access": "public"
  },
  "main": "src/index.js",
  "exports": {
    ".": "./src/index.js"
  },
  "files": [
    "src",
    "assets",
    "scripts",
    "README.md"
  ],
  "scripts": {
    "test": "node --test",
    "snapshot:capabilities": "node scripts/refresh-offline-capabilities.js"
  },
  "engines": {
    "node": ">=18"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "commandcode",
    "command-code",
    "provider",
    "goat",
    "ai"
  ],
  "license": "MIT"
}
